import{_ as e,o as r,c as d,a3 as a}from"./chunks/framework.D1iekJsc.js";const g=JSON.parse('{"title":"無料クラウド","description":"MiniTavern の無料クラウド API — 各社の無料／体験枠と永久無料モデル、BYOK 接続。有料 Key なしで始める方法。","frontmatter":{"title":"無料クラウド","description":"MiniTavern の無料クラウド API — 各社の無料／体験枠と永久無料モデル、BYOK 接続。有料 Key なしで始める方法。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"無料クラウド · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern の無料クラウド API — 各社の無料／体験枠と永久無料モデル、BYOK 接続。有料 Key なしで始める方法。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/free-cloud"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/free-cloud"}]]},"headers":[],"relativePath":"ja/free-cloud/index.md","filePath":"ja/free-cloud/index.md","lastUpdated":1787224147000}'),o={name:"ja/free-cloud/index.md"};function n(i,t,l,s,h,c){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="無料クラウド" tabindex="-1">無料クラウド <a class="header-anchor" href="#無料クラウド" aria-label="Permalink to &quot;無料クラウド&quot;">​</a></h1><p>MiniTavern は <strong>BYOK（自分の鍵を使う）</strong> です。アプリ側のクラウド枠はなく、各社・推論プラットフォームの API Key を自分で用意します。<br> ここではよくある <strong>無料／体験枠</strong> と App への記入方法をまとめます。枠や規約は変わるため、<strong>各公式コンソールの表示を正</strong>としてください。</p><blockquote><p>安全：API Key はパスワードと同じです。App の端末内保存にだけ入れ、チャット・スクショ・公開リポジトリに出さないでください。</p></blockquote><h2 id="まず一番早いルートを選ぶ" tabindex="-1">まず一番早いルートを選ぶ <a class="header-anchor" href="#まず一番早いルートを選ぶ" aria-label="Permalink to &quot;まず一番早いルートを選ぶ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状況</th><th>おすすめ</th><th>App プラットフォーム</th></tr></thead><tbody><tr><td>中国本土で早くチャットしたい</td><td><a href="#智譜-ai-glm">智譜 Flash 無料</a> または <a href="#siliconflow">SiliconFlow 無料</a></td><td>Custom (OpenAI)</td></tr><tr><td>1 つの Key でテキスト＋画像</td><td><a href="/ultra_guides/ja/free-cloud/agnes-ai">Agnes AI</a></td><td>Custom (OpenAI) / Images</td></tr><tr><td>1 つの Key で GPT / Gemini 等 <code>*-free</code>＋画像</td><td><a href="/ultra_guides/ja/free-cloud/aihubmix">AIHubMix</a></td><td>Custom (OpenAI) / Images</td></tr><tr><td>コーディング向けゲートウェイ、期限付き Free テキスト</td><td><a href="/ultra_guides/ja/free-cloud/opencode-zen">OpenCode Zen</a></td><td>Custom (OpenAI)</td></tr><tr><td>公式中国語 LLM の体験</td><td><a href="#通義千問--アリババクラウド百煉">通義千問 · アリババ百煉</a></td><td>Qwen</td></tr><tr><td>推論／コード向け</td><td><a href="#deepseek">DeepSeek</a></td><td>DeepSeek</td></tr><tr><td>海外アカウント・マルチモーダルテキスト</td><td><a href="#google-gemini">Google Gemini</a></td><td>Gemini(Google)</td></tr><tr><td>1 つの Key で多数の無料 OSS モデル</td><td><a href="/ultra_guides/ja/free-cloud/openrouter">OpenRouter <code>:free</code></a></td><td>OpenRouter</td></tr><tr><td>他の無料ベンダーを探す</td><td><a href="/ultra_guides/ja/free-cloud/freellm">FreeLLM 一覧</a>（<a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">awesome-freellm-apis</a>）</td><td>一覧参照</td></tr><tr><td>超低遅延の OSS 推論</td><td><a href="#groq">Groq</a></td><td>Custom (OpenAI)</td></tr><tr><td>クラウドを使わない</td><td><a href="/ultra_guides/ja/local/">ローカルモデル</a></td><td>Custom (OpenAI)</td></tr></tbody></table><p>Key の一般手順は <a href="/ultra_guides/ja/manual/model-link">モデル接続</a>。ローカルは <a href="/ultra_guides/ja/local/">ローカルモデル</a> · <a href="/ultra_guides/ja/quickstart">30 分クイックスタート</a>。</p><h2 id="minitavern-での記入方法" tabindex="-1">MiniTavern での記入方法 <a class="header-anchor" href="#minitavern-での記入方法" aria-label="Permalink to &quot;MiniTavern での記入方法&quot;">​</a></h2><p>経路：<strong>設定 → モデル → モデル接続 → 新規</strong></p><ol><li><strong>モデルプラットフォーム</strong>を正しく選ぶ（下表「App プラットフォーム」列）。</li><li><strong>API Key</strong> を貼る。カスタムの場合は <strong>Base URL</strong> も。</li><li><strong>モデル ID</strong> を選択／手入力（ベンダー文書と完全一致、大文字小文字区別）。</li><li><strong>テスト</strong> → 成功したら <strong>デフォルト</strong> に設定。</li></ol><table tabindex="0"><thead><tr><th>ベンダー</th><th>App プラットフォーム</th><th>Base URL（一般）</th><th>説明</th></tr></thead><tbody><tr><td>Gemini</td><td>Gemini(Google)</td><td>プリセットで可</td><td>Gemini プロトコル。OpenAI として入れない</td></tr><tr><td>OpenRouter</td><td>OpenRouter</td><td>プリセットで可</td><td>無料 ID はしばしば <code>:free</code></td></tr><tr><td>通義／百煉</td><td>Qwen</td><td>プリセット（国際サイト切替可）</td><td><strong>汎用</strong> API Key。Coding Plan 専用 Key は不可</td></tr><tr><td>DeepSeek</td><td>DeepSeek</td><td>プリセットで可</td><td></td></tr><tr><td>智譜／SiliconFlow／Agnes／AIHubMix／Zen／Groq／Mistral など</td><td><strong>Custom (OpenAI)</strong></td><td>各節参照</td><td>OpenAI 互換ゲートウェイ</td></tr></tbody></table><hr><h2 id="中国本土でよく使う-直結優先" tabindex="-1">中国本土でよく使う（直結優先） <a class="header-anchor" href="#中国本土でよく使う-直結優先" aria-label="Permalink to &quot;中国本土でよく使う（直結優先）&quot;">​</a></h2><h3 id="智譜-ai-glm" tabindex="-1">智譜 AI (GLM) <a class="header-anchor" href="#智譜-ai-glm" aria-label="Permalink to &quot;智譜 AI (GLM)&quot;">​</a></h3><p>向いている人：<strong>長期無料</strong>で会話を通したい（Flash 系）、中国語ロールプレイ向き。</p><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>公式／Key</td><td><a href="https://open.bigmodel.cn" target="_blank" rel="noreferrer">open.bigmodel.cn</a> → コンソール → API Keys</td></tr><tr><td>無料</td><td><code>GLM-*-Flash</code> など永久無料；新規は体験枠があること多（コンソール確認）</td></tr><tr><td>カード紐付け</td><td>通常不要</td></tr><tr><td>Base URL</td><td><code>https://open.bigmodel.cn/api/paas/v4</code></td></tr><tr><td>モデル例</td><td><code>glm-4.5-flash</code>、<code>glm-4.7-flash</code>（モデル広場の名称に従う）</td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><p>手順：登録 → API Key 作成 → Custom (OpenAI) → Base URL と Key → Flash 系 ID → 接続テスト。</p><h3 id="siliconflow-硅基流動" tabindex="-1">SiliconFlow（硅基流動） <a class="header-anchor" href="#siliconflow-硅基流動" aria-label="Permalink to &quot;SiliconFlow（硅基流動）&quot;">​</a></h3><p>向いている人：1 Key で複数 OSS チャット；画像にも無料枠がある場合あり。</p><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>公式／Key</td><td><a href="https://cloud.siliconflow.cn" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a> → アカウント → API キー</td></tr><tr><td>無料</td><td><strong>無料モデル</strong>は課金なし（名前に <code>Pro/</code> なし）；実名後に全無料モデル利用可</td></tr><tr><td>制限</td><td>モデル固定 RPM/TPM；<a href="https://docs.siliconflow.cn/cn/userguide/rate-limits/rate-limit-and-upgradation" target="_blank" rel="noreferrer">Rate Limits</a></td></tr><tr><td>Base URL</td><td><code>https://api.siliconflow.cn/v1</code></td></tr><tr><td>モデル例</td><td>広場の「免费」タグ、例 <code>Qwen/Qwen3-8B</code>（一覧は変動）</td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><p>注意：同名でも無料と <code>Pro/...</code> 課金版がある。誤りは課金。請求で無料モデル消費は 0 のはず。</p><h3 id="通義千問-·-アリババクラウド百煉" tabindex="-1">通義千問 · アリババクラウド百煉 <a class="header-anchor" href="#通義千問-·-アリババクラウド百煉" aria-label="Permalink to &quot;通義千問 · アリババクラウド百煉&quot;">​</a></h3><p>向いている人：公式 Qwen 系；MiniTavern に <strong>Qwen</strong> プリセットあり。</p><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>開通</td><td><a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">百煉コンソール</a>（華北 2／北京）で規約同意後自動開通</td></tr><tr><td>無料</td><td><strong>新規無料枠</strong>：多くのモデルで約 <strong>100 万 Token／モデル</strong>、約 <strong>90 日</strong>；モデル間で共有不可</td></tr><tr><td>Key</td><td>百煉 → API-Key；<strong>汎用 Key</strong>（Token Plan／Coding Plan 専用は無料枠を<strong>消費しない</strong>）</td></tr><tr><td>App</td><td><strong>Qwen</strong>（国内プリセット；国際サイト切替可）</td></tr><tr><td>課金防止</td><td>コンソールで「<strong>無料枠終了で停止</strong>」を有効化</td></tr></tbody></table><p>公式：<a href="https://help.aliyun.com/zh/model-studio/new-free-quota" target="_blank" rel="noreferrer">新規無料枠</a>。枠終了・期限後は従量課金。</p><p>画像（万相／Qwen-Image など）が新規枠対象なら <strong>設定 → 画像生成 → 画像接続 → Qwen</strong>。無料かはコンソールの枠表示で確認。</p><h3 id="deepseek" tabindex="-1">DeepSeek <a class="header-anchor" href="#deepseek" aria-label="Permalink to &quot;DeepSeek&quot;">​</a></h3><p>向いている人：推論・長文・コスパ良好。枠終了後は安いが <strong>永久 0 円ではない</strong>。</p><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>公式／Key</td><td><a href="https://platform.deepseek.com" target="_blank" rel="noreferrer">platform.deepseek.com</a> → API Keys</td></tr><tr><td>無料</td><td>新規は<strong>登録ボーナス／体験枠</strong>があることが多い（金額はコンソール）</td></tr><tr><td>App</td><td><strong>DeepSeek</strong></td></tr><tr><td>モデル例</td><td><code>deepseek-v4-flash</code>、<code>deepseek-v4-pro</code>（<a href="https://api-docs.deepseek.com/zh-cn/" target="_blank" rel="noreferrer">公式</a>）</td></tr></tbody></table><p>ボーナス後は従量。残高なしだと失敗。</p><h3 id="modelscope-api-inference" tabindex="-1">ModelScope API-Inference <a class="header-anchor" href="#modelscope-api-inference" aria-label="Permalink to &quot;ModelScope API-Inference&quot;">​</a></h3><p>向いている人：アリババ実名済みでコミュニティ OSS 推論を試したい。</p><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>Token</td><td><a href="https://modelscope.cn" target="_blank" rel="noreferrer">modelscope.cn</a> → アクセストークン</td></tr><tr><td>無料</td><td>登録ユーザーの日次リクエスト枠（<a href="https://modelscope.cn/docs/model-service/API-Inference/limits" target="_blank" rel="noreferrer">公式上限</a>）</td></tr><tr><td>Base URL</td><td><code>https://api-inference.modelscope.cn/v1</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><hr><h2 id="国際-集約プラットフォーム" tabindex="-1">国際／集約プラットフォーム <a class="header-anchor" href="#国際-集約プラットフォーム" aria-label="Permalink to &quot;国際／集約プラットフォーム&quot;">​</a></h2><h3 id="agnes-ai" tabindex="-1">Agnes AI <a class="header-anchor" href="#agnes-ai" aria-label="Permalink to &quot;Agnes AI&quot;">​</a></h3><p>1 つの無料 Key で <strong>テキストと画像</strong>（Flash 無料帯）。動画は公式サイト；App に動画入口は未実装。</p><p>詳細：<strong><a href="/ultra_guides/ja/free-cloud/agnes-ai">Agnes AI</a></strong>。</p><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>公式／Key</td><td><a href="https://agnes-ai.com/" target="_blank" rel="noreferrer">agnes-ai.com</a> · <a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a></td></tr><tr><td>無料</td><td>Free Access：Flash テキスト／画像（RPM 制限）</td></tr><tr><td>Base URL</td><td><code>https://apihub.agnes-ai.com/v1</code></td></tr><tr><td>テキスト例</td><td><code>agnes-2.5-flash</code></td></tr><tr><td>画像例</td><td><code>agnes-image-2.1-flash</code>（<strong>Custom (OpenAI Images)</strong>）</td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong> / <strong>Custom (OpenAI Images)</strong></td></tr></tbody></table><h3 id="opencode-zen" tabindex="-1">OpenCode Zen <a class="header-anchor" href="#opencode-zen" aria-label="Permalink to &quot;OpenCode Zen&quot;">​</a></h3><p>OpenCode 厳選ゲートウェイの <strong>Free テキスト</strong>（例 <code>mimo-v2.5-free</code>）。旗艦は従量が多い。自動チャージに注意。</p><p>詳細：<strong><a href="/ultra_guides/ja/free-cloud/opencode-zen">OpenCode Zen</a></strong>。</p><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>公式／Key</td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a> · <a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">ドキュメント</a></td></tr><tr><td>無料</td><td>価格表で Free のモデル（上限内）</td></tr><tr><td>Base URL</td><td><code>https://opencode.ai/zen/v1</code></td></tr><tr><td>テキスト例</td><td><code>mimo-v2.5-free</code>、<code>hy3-free</code>、<code>big-pickle</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong>（chat/completions 互換 ID 優先）</td></tr></tbody></table><h3 id="aihubmix" tabindex="-1">AIHubMix <a class="header-anchor" href="#aihubmix" aria-label="Permalink to &quot;AIHubMix&quot;">​</a></h3><p>1 Key で補助金付き <code>*-free</code>（GPT／Gemini／GLM 等）と <strong>GPT-Image-2-free</strong>。カード不要なことが多い。</p><p>詳細：<strong><a href="/ultra_guides/ja/free-cloud/aihubmix">AIHubMix</a></strong>。</p><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>公式／Key</td><td><a href="https://aihubmix.com" target="_blank" rel="noreferrer">aihubmix.com</a> · <a href="https://docs.aihubmix.com/cn/blogs/free-ai-models" target="_blank" rel="noreferrer">無料モデル記事</a></td></tr><tr><td>無料</td><td>ID が <code>-free</code> で終わる；モデル別 RPM／日枠</td></tr><tr><td>Base URL</td><td><code>https://aihubmix.com/v1</code></td></tr><tr><td>テキスト例</td><td><code>gpt-4o-free</code>、<code>gpt-5.5-free</code>、<code>coding-glm-5.1-free</code></td></tr><tr><td>画像例</td><td><code>gpt-image-2-free</code>（<strong>Custom (OpenAI Images)</strong>）</td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong> / <strong>Custom (OpenAI Images)</strong></td></tr></tbody></table><h3 id="google-gemini" tabindex="-1">Google Gemini <a class="header-anchor" href="#google-gemini" aria-label="Permalink to &quot;Google Gemini&quot;">​</a></h3><p>マルチモーダルテキスト・長コンテキスト。<strong>テキスト</strong>無料枠は比較的厚い。</p><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer">aistudio.google.com/app/apikey</a></td></tr><tr><td>無料</td><td>一部 Gemini Flash／Lite <strong>テキスト</strong>に Free tier（RPM／RPD は AI Studio 表示）</td></tr><tr><td>カード</td><td>テキスト無料は通常不要；<strong>新しい画像モデルの多くは Free なし</strong></td></tr><tr><td>地域</td><td>EU／英国／スイス等は無料枠不可の場合あり</td></tr><tr><td>プライバシー</td><td>無料枠のプロンプトが製品改善に使われる場合あり</td></tr><tr><td>App</td><td><strong>Gemini(Google)</strong></td></tr></tbody></table><p>チャットはテキストモデル（例 <code>gemini-flash-latest</code>）。<code>tts</code>／<code>image</code> 付き専用 ID は選ばない — テストは TEXT を要求し、TTS は AUDIO のみ → <code>response modalities (TEXT) is not supported</code>。</p><p><code>HTTP 404</code>＋<code>no longer available to new users</code>：ID 廃止／新規非公開（例 <code>gemini-2.5-flash-lite</code>）。最新一覧を取得し、稼働中の Flash／Lite（例 <code>gemini-flash-latest</code>）へ。</p><p><code>HTTP 429</code>＋<code>generate_content_free_tier_requests</code>（よく limit: 20）：無料枠の分あたり上限。<code>Please retry in …</code> に従う。<a href="https://ai.dev/rate-limit" target="_blank" rel="noreferrer">ai.dev/rate-limit</a>。</p><p>画像：Gemini <strong>App</strong> と <strong>Developer API</strong> は枠が別。API 画像は Free 不可表記が多い。チャット＝Gemini、画像＝自宅 A1111／ComfyUI が定番 — <a href="/ultra_guides/ja/local/image-gen/">画像モデル展開</a>。</p><h3 id="openrouter" tabindex="-1">OpenRouter <a class="header-anchor" href="#openrouter" aria-label="Permalink to &quot;OpenRouter&quot;">​</a></h3><p>1 Key で大量の <strong>OSS／第三者無料プール</strong>。ID はしばしば <code>:free</code>。詳細：<strong><a href="/ultra_guides/ja/free-cloud/openrouter">OpenRouter</a></strong>。</p><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>無料</td><td><code>:free</code>／コレクション Free；約 20 RPM、日リクエスト制限；チャージで日上限増の場合あり</td></tr><tr><td>App</td><td><strong>OpenRouter</strong></td></tr><tr><td>モデル例</td><td><code>openrouter/free</code>、<code>meta-llama/llama-3.3-70b-instruct:free</code>、<code>openai/gpt-oss-20b:free</code></td></tr><tr><td>コレクション</td><td><a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a> · <a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a></td></tr></tbody></table><p>注意：無料上流はプロンプトを学習に使う場合あり。<code>HTTP 429: Provider returned error</code> → 別 <code>:free</code>、再試行、または <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">BYOK</a>。</p><h3 id="groq" tabindex="-1">Groq <a class="header-anchor" href="#groq" aria-label="Permalink to &quot;Groq&quot;">​</a></h3><p><strong>超低遅延</strong>の OSS 推論向け。</p><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://console.groq.com/keys" target="_blank" rel="noreferrer">console.groq.com/keys</a></td></tr><tr><td>無料</td><td>永久 Free tier（モデル別 RPM／RPD／TPM、変動あり）</td></tr><tr><td>カード</td><td>通常不要</td></tr><tr><td>Base URL</td><td><code>https://api.groq.com/openai/v1</code></td></tr><tr><td>モデル例</td><td><code>llama-3.1-8b-instant</code>、<code>llama-3.3-70b-versatile</code>、<code>openai/gpt-oss-20b</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><h3 id="mistral-ai" tabindex="-1">Mistral AI <a class="header-anchor" href="#mistral-ai" aria-label="Permalink to &quot;Mistral AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://console.mistral.ai/api-keys" target="_blank" rel="noreferrer">console.mistral.ai/api-keys</a></td></tr><tr><td>無料</td><td>Experiment／試用（月 Token はコンソール）；プロンプト改善利用の可能性</td></tr><tr><td>Base URL</td><td><code>https://api.mistral.ai/v1</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><h3 id="cerebras-sambanova-など高速推論" tabindex="-1">Cerebras／SambaNova など高速推論 <a class="header-anchor" href="#cerebras-sambanova-など高速推論" aria-label="Permalink to &quot;Cerebras／SambaNova など高速推論&quot;">​</a></h3><table tabindex="0"><thead><tr><th>プラットフォーム</th><th>Key</th><th>Base URL</th><th>備考</th></tr></thead><tbody><tr><td>Cerebras</td><td><a href="https://cloud.cerebras.ai/" target="_blank" rel="noreferrer">cloud.cerebras.ai</a></td><td><code>https://api.cerebras.ai/v1</code></td><td>無料は日 Token 上限が多い；決済手段要求の場合あり</td></tr><tr><td>SambaNova</td><td><a href="https://cloud.sambanova.ai/apis" target="_blank" rel="noreferrer">cloud.sambanova.ai</a></td><td><code>https://api.sambanova.ai/v1</code></td><td>永久無料＋一時ボーナス；制限厳しめ</td></tr></tbody></table><p>App はいずれも <strong>Custom (OpenAI)</strong>。モデル名は各コンソール準拠。</p><h3 id="github-models" tabindex="-1">GitHub Models <a class="header-anchor" href="#github-models" aria-label="Permalink to &quot;GitHub Models&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>入口</td><td><a href="https://github.com/marketplace/models" target="_blank" rel="noreferrer">GitHub Models</a></td></tr><tr><td>認証</td><td>GitHub Personal Access Token</td></tr><tr><td>Base URL</td><td><code>https://models.github.ai/inference</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr><tr><td>制限</td><td>モデル別 RPM／RPD — 軽い試用向き</td></tr></tbody></table><h3 id="nvidia-nim" tabindex="-1">NVIDIA NIM <a class="header-anchor" href="#nvidia-nim" aria-label="Permalink to &quot;NVIDIA NIM&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>入口</td><td><a href="https://build.nvidia.com/explore/discover" target="_blank" rel="noreferrer">build.nvidia.com</a></td></tr><tr><td>Base URL</td><td><code>https://integrate.api.nvidia.com/v1</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong>（将来 Nvidia プリセットが戻れば選択可）</td></tr></tbody></table><hr><h2 id="体験枠-永久無料ではない" tabindex="-1">体験枠（永久無料ではない） <a class="header-anchor" href="#体験枠-永久無料ではない" aria-label="Permalink to &quot;体験枠（永久無料ではない）&quot;">​</a></h2><p>評価向き。長期の唯一バックエンドには不向き：</p><table tabindex="0"><thead><tr><th>ベンダー</th><th>よくある状況</th><th>App</th></tr></thead><tbody><tr><td>OpenAI</td><td>コンソールに一時クレジット；本家 API に <strong>安定した永久無料なし</strong></td><td>ChatGPT(OpenAI)</td></tr><tr><td>Anthropic Claude</td><td>starter credits、すぐ減る</td><td>Claude(Anthropic)</td></tr><tr><td>DeepSeek</td><td>上記登録ボーナス</td><td>DeepSeek</td></tr><tr><td>アリババ百煉</td><td>新規 Token 枠（約 90 日）</td><td>Qwen</td></tr></tbody></table><p>使い切ったら：Key 削除、「枠終了で停止」、無料モデル／ローカルへ切替。</p><hr><h2 id="無料の画像生成" tabindex="-1">無料の画像生成 <a class="header-anchor" href="#無料の画像生成" aria-label="Permalink to &quot;無料の画像生成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>経路</th><th>費用</th><th>説明</th></tr></thead><tbody><tr><td><a href="/ultra_guides/ja/local/image-gen/">自宅 A1111／ComfyUI</a></td><td>電気＋GPU</td><td>枚数制限なし；スマホ→PC LAN</td></tr><tr><td>SiliconFlow 無料画像モデル</td><td>無料モデルは 0 円</td><td>画像接続 <strong>Custom (OpenAI Images)</strong>、Base URL は硅基 <code>…/v1</code></td></tr><tr><td><a href="/ultra_guides/ja/free-cloud/agnes-ai">Agnes AI</a> Image Flash</td><td>Free Access</td><td><strong>Custom (OpenAI Images)</strong>、<code>https://apihub.agnes-ai.com/v1</code>、例 <code>agnes-image-2.1-flash</code></td></tr><tr><td><a href="/ultra_guides/ja/free-cloud/aihubmix">AIHubMix</a></td><td><code>*-free</code> 画像</td><td><strong>Custom (OpenAI Images)</strong>、<code>https://aihubmix.com/v1</code>、例 <code>gpt-image-2-free</code></td></tr><tr><td>通義万相／Qwen 画像</td><td>百煉の当該枠を確認</td><td><strong>設定 → 画像生成 → 画像接続 → Qwen</strong></td></tr><tr><td>OpenAI／多くの Gemini 画像 API</td><td>通常有料</td><td>安定 Free がなければ「無料画像」にしない</td></tr></tbody></table><p>チャットと画像接続は分離可：例・チャット＝智譜 Flash、画像＝自宅 ComfyUI。</p><hr><h2 id="使い方のコツとトラブル" tabindex="-1">使い方のコツとトラブル <a class="header-anchor" href="#使い方のコツとトラブル" aria-label="Permalink to &quot;使い方のコツとトラブル&quot;">​</a></h2><ol><li><strong>先に接続テスト</strong>：失敗時は「詳細」→ <a href="/ultra_guides/ja/manual/errors">エラーコード</a>。</li><li><strong>429／レート制限</strong>：軽いモデル、記憶短縮、別無料枠。</li><li><strong>突然の課金</strong>：<code>Pro/</code> モデル？百煉の停止未設定？ボーナス切れ？</li><li><strong>プライバシー</strong>：無料枠はログ改善利用が多い — 機密は <a href="/ultra_guides/ja/local/">ローカル</a>。</li><li><strong>枠の変更</strong>：数値は調査時点の目安。索引は <a href="/ultra_guides/ja/free-cloud/freellm">FreeLLM</a>（<a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">awesome-freellm-apis</a> · <a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a>）。</li></ol><h2 id="関連章" tabindex="-1">関連章 <a class="header-anchor" href="#関連章" aria-label="Permalink to &quot;関連章&quot;">​</a></h2><ul><li><a href="/ultra_guides/ja/manual/model-link">モデル接続</a> — App での記入</li><li><a href="/ultra_guides/ja/manual/getting-started">はじめての利用</a></li><li><a href="/ultra_guides/ja/free-cloud/freellm">FreeLLM 一覧</a></li><li><a href="/ultra_guides/ja/local/">ローカルモデル</a></li><li><a href="/ultra_guides/ja/local/image-gen/">画像モデル展開</a> — A1111／ComfyUI</li></ul>',83)])])}const u=e(o,[["render",n]]);export{g as __pageData,u as default};
